-- The aggregate keeps the package and its departures atomic, including concurrent edits.
create table public.travel_packages (
 id uuid primary key default gen_random_uuid(),
 store_id uuid not null references public.stores(id) on delete cascade,
 source_key text,
 status text not null default 'draft' check (status in ('draft','published','paused','archived')),
 content jsonb not null,
 version integer not null default 1,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 unique(store_id,source_key),
 check (jsonb_typeof(content) = 'object' and octet_length(content::text) <= 1000000)
);
create unique index travel_packages_pdf_hash_idx on public.travel_packages(store_id,(content->>'source_hash')) where coalesce(content->>'source_hash','')<>'';
create index travel_packages_public_idx on public.travel_packages(store_id,status);
alter table public.travel_packages enable row level security;
revoke all on public.travel_packages from public,anon,authenticated;
grant select on public.travel_packages to anon,authenticated;
grant insert,delete on public.travel_packages to authenticated;
grant update (content,status) on public.travel_packages to authenticated;
grant all on public.travel_packages to service_role;
create policy travel_packages_read on public.travel_packages for select to anon,authenticated using (
 exists (select 1 from public.stores s where s.id=store_id and s.slug='luxury-travel-point' and s.is_active)
 and (status='published' or (public.has_store_role(store_id,array['OWNER','ADMIN']) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active)))
);
create policy travel_packages_write on public.travel_packages for all to authenticated using (
 public.has_store_role(store_id,array['OWNER','ADMIN'])
 and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active)
 and exists(select 1 from public.stores s where s.id=store_id and s.slug='luxury-travel-point' and s.is_active)
) with check (
 public.has_store_role(store_id,array['OWNER','ADMIN'])
 and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active)
 and exists(select 1 from public.stores s where s.id=store_id and s.slug='luxury-travel-point' and s.is_active)
);
create function private.validate_travel_package() returns trigger language plpgsql set search_path='' as $$
declare k text; item jsonb; departure jsonb; rate jsonb; value text;
begin
 if tg_op='UPDATE' then
  if new.store_id<>old.store_id or new.id<>old.id then raise exception 'No se puede cambiar la agencia del paquete.'; end if;
  new.version:=old.version+1;
 end if;
 new.updated_at:=now();
 if coalesce(length(btrim(new.content->>'title')),0) not between 1 and 200
  or coalesce(new.content->>'category','') not in ('group','custom','cruise')
  or (new.content->'days' is distinct from 'null'::jsonb and (coalesce(new.content->>'days','') !~ '^[0-9]{1,3}$' or (new.content->>'days')::integer not between 1 and 365))
  or coalesce(jsonb_typeof(new.content->'permanent'),'')<>'boolean'
  or coalesce(jsonb_typeof(new.content->'featured'),'')<>'boolean'
  or coalesce(new.content->>'sort_order','') !~ '^-?[0-9]{1,6}$'
 then raise exception 'Datos del paquete inválidos.'; end if;
 foreach k in array array['description','route','accommodation','conditions','source_text','source_url','pdf','image'] loop
  if coalesce(jsonb_typeof(new.content->k),'')<>'string' then raise exception 'Campo inválido: %',k; end if;
 end loop;
 foreach k in array array['countries','includes','excludes','gallery','itinerary','departures'] loop
  if coalesce(jsonb_typeof(new.content->k),'')<>'array' or jsonb_array_length(new.content->k)>365 then raise exception 'Listado inválido: %',k; end if;
 end loop;
 foreach k in array array['countries','includes','excludes','gallery'] loop
  for item in select * from jsonb_array_elements(new.content->k) loop
   if jsonb_typeof(item)<>'string' then raise exception 'Listado inválido: %',k; end if;
  end loop;
 end loop;
 for item in select * from jsonb_array_elements(new.content->'itinerary') loop
  if coalesce(jsonb_typeof(item->'title'),'')<>'string' or coalesce(jsonb_typeof(item->'description'),'')<>'string' then raise exception 'Itinerario inválido.'; end if;
 end loop;
 for departure in select * from jsonb_array_elements(new.content->'departures') loop
  if coalesce(departure->>'id','')='' or coalesce(departure->>'status','') not in ('available','sold_out','closed')
    or coalesce(jsonb_typeof(departure->'rates'),'')<>'array' then raise exception 'Salida inválida.'; end if;
  foreach k in array array['start','end','deadline','origin','pdf'] loop
   if coalesce(jsonb_typeof(departure->k),'')<>'string' then raise exception 'Campo de salida inválido: %',k; end if;
  end loop;
  foreach k in array array['start','end','deadline'] loop
   value:=departure->>k;
   if value<>'' and (value !~ '^\d{4}-\d{2}-\d{2}$' or (value::date)::text<>value) then raise exception 'Fecha inválida.'; end if;
  end loop;
  if (departure->>'end'<>'' and (departure->>'start'='' or departure->>'end'<departure->>'start'))
    or (departure->>'deadline'<>'' and (departure->>'start'='' or departure->>'deadline'>departure->>'start')) then raise exception 'Revisa las fechas de regreso y cierre de reservas.'; end if;
  if new.status='published' and departure->>'start'='' then raise exception 'Falta la fecha de salida.'; end if;
  for rate in select * from jsonb_array_elements(departure->'rates') loop
   if coalesce(length(btrim(rate->>'label')),0)=0 or coalesce(jsonb_typeof(rate->'amount'),'')<>'number' or (rate->>'amount')::numeric<0 then raise exception 'Tarifa inválida.'; end if;
  end loop;
 end loop;
 if exists(select 1 from jsonb_array_elements(new.content->'departures') d group by d->>'id' having count(*)>1) then raise exception 'Hay salidas repetidas.'; end if;
 if new.status='published' and (new.content->>'image'='' or btrim(new.content->>'description')='' or new.content->'countries'='[]') then raise exception 'Completa la portada, descripción y destinos antes de publicar.'; end if;
 return new;
end $$;
revoke all on function private.validate_travel_package() from public,anon,authenticated;
create trigger validate_travel_package before insert or update on public.travel_packages for each row execute function private.validate_travel_package();

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values ('travel-assets','travel-assets',true,31457280,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy travel_assets_insert on storage.objects for insert to authenticated with check (
 bucket_id='travel-assets'
 and public.has_store_role((storage.foldername(name))[1]::uuid,array['OWNER','ADMIN'])
 and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active)
 and exists(select 1 from public.stores s where s.id::text=(storage.foldername(name))[1] and s.slug='luxury-travel-point' and s.is_active)
);
